ANNOTATIONS = [
    (1, 'before', '''旋转指示器（spinner）里那句会「流动发光」的文案。整份文件只做一件事：把一条消息按**字素簇**切成 before / shimmer / after 三段，中间那段换成高亮色再拼回去。看着像纯装饰，但里面每一处都在处理终端特有的坑：宽字符、非 BMP 字符、颜色模块缺失、以及「为什么末尾要多渲染一个空格」。'''),
    (9, 'before', '''Props 里 `messageColor` 与 `shimmerColor` 的类型都是 `keyof Theme` 而不是字符串——这样主题里改名会编译报错。`glimmerIndex` 是「发光点当前在第几列」，由外层动画每帧推进；组件本身无状态，也就没有动画定时器。'''),
    (18, 'before', '''ERROR_RED 是一个写死的 RGB 三元组，不是主题色。用途是「卡住」状态：把消息色朝这个红插值（interpolateColor），插值系数由外层给的 stalledIntensity 控制。写死不进主题，是因为它要作为一个**基准色**参与插值，主题里改它会连带改变插值数学。'''),
    (40, 'before', '''`Symbol.for(「react.early_return_sentinel」)` 是编译器为「函数体里有提前 return」准备的值：整个 bb0 块可能提前返回（空消息、卡住态、tool-use 态），所以结果先写进 t2，块外再判断「是不是哨兵」决定要不要直接返回。读法：t2 有值且不是哨兵 → 直接 return t2。'''),
    (41, 'before', '''`bb0: {` 是带标签的裸块，`break bb0` 相当于跳到块尾。编译器用这个模式把源码里四个 `return` 收敛成一个出口，好让缓存写入只出现在一处。它不是业务语法，不要当成「命名块分组」。'''),
    (46, 'before', '''按**字素簇**（grapheme cluster）切分而不是按 char / code unit：emoji（尤其带 ZWJ 的组合 emoji）、组合音标都必须在一次切分里完整取出，否则会被切成两半、渲染成两个豆腐块。同时每个簇单独算 `stringWidth`，因为终端里一个字符可能占 2 列。'''),
    (61, 'before', '''整条消息的总显示宽度单独算一次（`stringWidth(message)`），**不是把各段宽度相加**。原因是 stringWidth 对整串可能有额外处理（例如变体选择符、行内 ANSI），相加不一定等于整体。这里以整体为准，各段宽度只用来定位切点。'''),
    (83, 'before', '''空消息直接返回 null（早退）。看起来是防御，实际是必要：上层在等待阶段会先渲染 `''`，若这里继续往下走就会算出 shimmerStart = -1、shimmerEnd = 1，然后渲染出一个纯空格的 Text——终端里表现为那一行莫名多出一个空格、把后面的内容推了一格。'''),
    (87, 'before', '''卡住态优先于 tool-use 态：只要 stalledIntensity > 0 就不再做流动效果，整条消息朝红色插值。这是一个「状态覆盖动画」的取舍——卡住时用户最需要的是「它没死但很慢」，让颜色呼吸反而误导。'''),
    (91, 'before', '''插值需要基准色是 RGB。`parseRGB(theme[messageColor])` 失败（主题里该色是 ANSI 索引色如 `red`，没有 RGB 表示）时返回 null，往下走降级分支。这就是为什么要先判断 `baseRGB` 再插值。'''),
    (104, 'before', '''降级分支：拿不到 RGB 就只能在两档里硬切——stalledIntensity 过半用 `error`，否则用原色。阈值 0.5 是**二值量化**的简化，视觉上会看到颜色「跳变」而不是渐变，这是无色值可用时唯一能做的。'''),
    (134, 'before', '''tool-use 模式：消息色朝 shimmerColor 插值，插值系数是 flashOpacity（外层给的闪烁透明度）。与卡住态不同，这里插的是**流动闪光的亮度**，所以插值对象是 shimmer 而不是错误色。两个分支结构几乎一样但基准色与系数不同，编译器没有合并它们。'''),
    (162, 'before', '''同样有无 RGB 的降级：flashOpacity 过半用 shimmerColor 否则原色。注意这里判断条件用的还是 `flashOpacity > 0.5`，与卡住态的 `stalledIntensity > 0.5` 是两个独立阈值——它们的含义不同（一个是闪烁相位，一个是卡住程度）。'''),
    (208, 'before', '''哨兵判断在块外。走到这里说明上面三个早退分支都没命中，要继续做流动效果。注意此时 messageWidth 与 segments 是从缓存槽读回来的（203-207 行），不是重新算的。'''),
    (211, 'before', '''发光窗口是 `[glimmerIndex - 1, glimmerIndex + 1]`，也就是**三列宽**：一列前导、一列高亮、一列拖尾。用半开区间加 1/-1 而不是宽度 3 的矩形，是为了让高亮看起来像「有方向的扫过」而不是「一个方块在跳」。'''),
    (213, 'before', '''窗口完全在消息之外（起点超过总宽，或终点还在 0 之前）时返回纯色版本。这个判断保证了循环动画在两端不会「半截悬空」——否则 glimmerIndex 绕回 0 时会看到右边缘突然亮一下。'''),
    (242, 'before', '''`clampedStart = Math.max(0, shimmerStart)` 只钳左端不钳右端：右端越界由分段的 `colPos > shimmerEnd` 条件自然处理（剩下的都进 after，after 为空就不渲染）。两处各管一半，是有意为之而不是漏钳。'''),
    (248, 'before', '''分段循环只有三条分支：整个段落在起点之前 → before；段起点已越过终点 → after；其余 → shimmer。判断用的是**段的起始列**而不是「与窗口相交」，这是简化：跨窗口边界的段会整段被划进 shimmer，视觉上就是高亮多覆盖一个宽字符——比把一个宽字符劈成两半安全得多。'''),
    (255, 'before', '''`colPos > shimmerEnd` 用严格大于而不是大于等于：终点那一列仍算高亮（闭区间语义）。这样三列窗口实际覆盖 `glimmerIndex-1 / glimmerIndex / glimmerIndex+1`，与上面 shimmerEnd 的定义对齐。'''),
    (309, 'before', '''每个分支末尾都渲染一个 `<Text color={messageColor}> </Text>`（一个空格）。这个尾随空格不是为了好看：终端里 Text 节点末尾的空白可能被 Ink 裁掉，若消息最后一列正好是高亮色，裁掉后颜色块会紧贴边框。固定补一个原色空格，等于给渲染结果一个确定的右边界。'''),
]
